function pageShowAddToCollection(itemType, itemID){
    const _t = (key) => (window.I18N && window.I18N[key]) ? window.I18N[key] : key;
    if (!window.isLoggedIn) {
        if (typeof showLoginConfirm === "function") {
            showLoginConfirm(_t("collection.login_to_add"), function(){ window.location.href = "login"; });
        } else {
            showSnackbar(_t("collection.login_to_add"));
        }
        return;
    }
    try {
        const url = window.APP_BASE + "?api-collections=1&action=list&itemType=" + encodeURIComponent(itemType) + "&itemID=" + encodeURIComponent(itemID) + "&ts=" + Date.now();
        fetch(url, { cache: "no-store" })
            .then(r => {
                if (r.status === 401) {
                    window.isLoggedIn = false;
                    if (typeof showLoginConfirm === "function") {
                        showLoginConfirm(_t("collection.login_to_add"), function(){ window.location.href = "login"; });
                    } else {
                        showSnackbar(_t("collection.login_to_add"));
                    }
                    return null;
                }
                return r.json();
            })
            .then(data => {
                if (!data) return;
                if (!Array.isArray(data.collections)) {
                    showSnackbar(_t("collection.load_failed"));
                    return;
                }
                const cols = data.collections.filter(c => !c.virtual && c.collectionType === itemType);
                if (typeof showCollectionPicker === "function") {
                    showCollectionPicker(cols, itemType, function(selectedCollectionID, info){
                        addToCollection(selectedCollectionID, itemType, itemID).then(success => {
                            if (success) {
                                const colName = (info && info.name) ? info.name : "";
                                markItemInCollection(itemType, itemID, colName);
                            }
                        });
                    }, itemID);
                }
            })
            .catch(() => showSnackbar(_t("collection.load_error")));
    } catch (e) {
        showSnackbar(_t("error.generic"));
    }
}


