function updateShareLinks(url, title) {
    var eu = encodeURIComponent(url);
    var et = encodeURIComponent(title);
    var dialog = document.querySelector('.share-dialog');
    if (!dialog) return;
    var links = dialog.querySelectorAll('.targets a');
    links.forEach(function(a) {
        var cls = a.className;
        if (cls.indexOf('facebookButton') > -1) a.href = 'https://www.facebook.com/sharer/sharer.php?u=' + eu;
        else if (cls.indexOf('twitterButton') > -1) a.href = 'http://twitter.com/share?text=' + et + '&url=' + eu;
        else if (a.href.indexOf('linkedin') > -1) a.href = 'https://www.linkedin.com/shareArticle?mini=true&url=' + eu + '&title=' + et;
        else if (a.href.indexOf('reddit') > -1) a.href = 'http://www.reddit.com/submit?url=' + eu + '&title=' + et;
        else if (a.href.indexOf('whatsapp') > -1) a.href = 'https://web.whatsapp.com/send?text=' + et + ' %0D%0A @' + eu;
        else if (a.href.indexOf('sms:') > -1) a.href = 'sms:?body=' + et + ' %0D%0A @' + eu;
        else if (a.href.indexOf('tumblr') > -1) a.href = 'https://www.tumblr.com/share?t=' + et + '&u=' + eu + '&v=3';
        else if (a.href.indexOf('vk.com') > -1) a.href = 'https://vk.com/share.php?url=' + eu;
        else if (a.href.indexOf('flipboard') > -1) a.href = 'https://share.flipboard.com/bookmarklet/popout?ext=clipcafe&title=' + et + '&url=' + eu + '&utm_campaign=widgets&utm_content=clip.cafe&utm_source=clipcafe&v=2';
    });
    // Also update copy link input
    var copyInput = dialog.parentElement ? dialog.parentElement.querySelector('input[type=text]') : null;
    if (copyInput) copyInput.value = url;
}

