// Tab switching for clip page
function switchClipTab(event, tabName) {
    const tabButtons = document.querySelectorAll('.clip-tab-btn');
    const tabContents = document.querySelectorAll('.clip-tab-content');

    tabButtons.forEach(btn => btn.classList.remove('active'));
    tabContents.forEach(content => content.classList.remove('active'));

    event.target.classList.add('active');
    document.getElementById('tab-' + tabName).classList.add('active');
}

// Switch subtitle transcript language
function switchSubtitleTranscript(el) {
    var lang = el.dataset.lang;
    var index = parseInt(el.dataset.index, 10);

    // Update buttons
    var buttons = document.querySelectorAll('.sub-lang-btn');
    buttons.forEach(function(btn) {
        btn.classList.remove('active');
        btn.setAttribute('aria-selected', 'false');
    });
    el.classList.add('active');
    el.setAttribute('aria-selected', 'true');

    // Switch panels with fade animation
    var panels = document.querySelectorAll('.transcript-panel');
    panels.forEach(function(panel) {
        if (panel.classList.contains('active')) {
            panel.classList.add('fading-out');
            setTimeout(function() {
                panel.classList.remove('active');
                panel.classList.remove('fading-out');
                panel.setAttribute('aria-hidden', 'true');
            }, 150);
        }
    });

    setTimeout(function() {
        var targetPanel = document.getElementById('transcript-panel-' + index);
        if (targetPanel) {
            targetPanel.classList.add('active');
            targetPanel.setAttribute('aria-hidden', 'false');
        }
    }, 150);
}

// Reactive like button
function likeClip(clipId) {
    const likeBtn = document.getElementById('like-btn-' + clipId);
    const counter = document.getElementById('thumbsup-counter');

    // Prevent double-voting
    if (likeBtn.dataset.voted === '1') return;

    // Add pulse animation
    likeBtn.classList.add('fav-clicked');
    setTimeout(() => likeBtn.classList.remove('fav-clicked'), 300);

    // Mark as liked
    likeBtn.classList.add('liked');
    likeBtn.dataset.voted = '1';

    // Optimistic counter increment
    const currentCount = parseInt(counter.textContent) || 0;
    counter.textContent = currentCount + 1;

    // Send to backend
    const basePath = (typeof window.APP_BASE === 'string' && window.APP_BASE) ? window.APP_BASE : '/';
    fetch(basePath + 'send/vote=' + clipId, { credentials: 'same-origin' })
        .then(r => r.json())
        .then(data => {
            // Update counter with actual server value
            counter.textContent = data.pro;
        })
        .catch(() => {});
    gurl('send/track=like&trackid=' + clipId);
}

// Comment sheet: move the single form into/out of the bottom sheet
function openCommentSheet() {
    const overlay = document.querySelector('.comment-sheet-overlay');
    const sheet = document.querySelector('.comment-sheet');
    const form = document.getElementById('commentFormContainer');
    const sheetBody = document.querySelector('.comment-sheet-body');
    if (!overlay || !sheet || !form || !sheetBody) return;

    // Move form into sheet
    sheetBody.appendChild(form);
    form.classList.add('in-sheet');

    overlay.classList.add('active');
    requestAnimationFrame(() => {
        sheet.classList.add('active');
    });
    document.body.classList.add('comment-sheet-open');

    // Focus textarea after animation
    setTimeout(() => {
        const textarea = document.getElementById('commentTextAreaBox');
        if (textarea && !textarea.hasAttribute('readonly')) {
            textarea.focus();
        }
    }, 350);
}

function closeCommentSheet() {
    const overlay = document.querySelector('.comment-sheet-overlay');
    const sheet = document.querySelector('.comment-sheet');
    const form = document.getElementById('commentFormContainer');
    const trigger = document.querySelector('.comment-trigger-mobile');
    if (!overlay || !sheet || !form) return;

    sheet.classList.remove('active');
    setTimeout(() => {
        overlay.classList.remove('active');
        // Move form back to its original position (after trigger)
        if (trigger && trigger.parentNode) {
            trigger.parentNode.insertBefore(form, trigger.nextSibling);
        }
        form.classList.remove('in-sheet');
    }, 300);
    document.body.classList.remove('comment-sheet-open');
}

document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
        closeCommentSheet();
    }
});

document.addEventListener('DOMContentLoaded', function() {
    var textarea = document.getElementById('commentTextAreaBox');
    if (textarea) {
        textarea.addEventListener('input', function() {
            this.style.height = 'auto';
            this.style.height = (this.scrollHeight) + 'px';
        });
    }
});

