                    console.log('lanscape locked');
                  })
                  .catch((error) => {
                    console.log('lanscape error',error);
                  });
            });

            player.on('exitfullscreen', event => {
                screen.orientation.lock('portrait');
            });

        }
};

function openSupportChat(){
